using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ──── AddItem ────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        var (qty, price) = _sut.Items["SKU-1"];
        Assert.AreEqual(2, qty);
        Assert.AreEqual(9.99m, price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 5.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctSkus_AllPresent()
    {
        _sut.AddItem("A", 1, 1.00m);
        _sut.AddItem("B", 1, 2.00m);
        _sut.AddItem("C", 1, 3.00m);

        Assert.AreEqual(3, _sut.Items.Count);
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    public void AddItem_NullSku_ThrowsArgumentNullException(string? sku)
    {
        Assert.ThrowsException<ArgumentNullException>(() => _sut.AddItem(sku!, 1, 1.00m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _sut.AddItem("SKU-1", quantity, 1.00m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _sut.AddItem("SKU-1", 1, -5.00m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _sut.AddItem("FREE", 1, 0.00m);

        Assert.AreEqual(0.00m, _sut.Items["FREE"].Price);
    }

    // ──── RemoveItem ────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 10.00m);
        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _sut.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _sut.RemoveItem(null!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetItem()
    {
        _sut.AddItem("A", 1, 1.00m);
        _sut.AddItem("B", 1, 2.00m);
        _sut.RemoveItem("A");

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.IsTrue(_sut.Items.ContainsKey("B"));
    }

    // ──── CalculateTotal ────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _sut.AddItem("SKU-1", 3, 4.50m);

        Assert.AreEqual(13.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 10.00m); // 20.00
        _sut.AddItem("B", 1, 5.50m);  // 5.50

        Assert.AreEqual(25.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 1, 10.00m);
        _sut.AddItem("B", 1, 20.00m);
        _sut.RemoveItem("A");

        Assert.AreEqual(20.00m, _sut.CalculateTotal());
    }

    // ──── ApplyCoupon ────

    [TestMethod]
    [DataRow("SAVE10", 90.00, DisplayName = "10% off")]
    [DataRow("SAVE20", 80.00, DisplayName = "20% off")]
    [DataRow("HALF", 50.00, DisplayName = "50% off")]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _sut.AddItem("SKU-1", 1, 100.00m);
        _sut.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _sut.CalculateTotal());
        Assert.AreEqual(code, _sut.AppliedCoupon);
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _sut.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacePreviousCoupon_UsesLatest()
    {
        _sut.AddItem("SKU-1", 1, 100.00m);
        _sut.ApplyCoupon("SAVE10");
        _sut.ApplyCoupon("SAVE20");

        Assert.AreEqual(80.00m, _sut.CalculateTotal());
        Assert.AreEqual("SAVE20", _sut.AppliedCoupon);
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_ReturnsFullPrice()
    {
        _sut.AddItem("SKU-1", 1, 100.00m);

        Assert.IsNull(_sut.AppliedCoupon);
        Assert.AreEqual(100.00m, _sut.CalculateTotal());
    }

    // ──── Rounding ────

    [TestMethod]
    public void CalculateTotal_WithCoupon_RoundsToTwoDecimals()
    {
        // 3 × 9.99 = 29.97 × 0.10 = 2.997 → total 26.973 → rounds to 26.97
        _sut.AddItem("SKU-1", 3, 9.99m);
        _sut.ApplyCoupon("SAVE10");

        Assert.AreEqual(26.97m, _sut.CalculateTotal());
    }
}

